        var r = lib.writeToTrackerField('77', 'description', 'body', 'replace', tracker);
        assert.equal(adoCalls.length, 1);
        assert.equal(String(adoCalls[0].id), '77');
        assert.equal(adoCalls[0].description, 'body');
        assert.equal(r.length, 4);
    });

