}

function loadWriteContentOutput(mocks, projectConfig, extraModules) {
    var configLoaderMock = {
        loadProjectConfig: function() { return projectConfig || {}; }
    };
    var modules = {
        './common/contentOutput.js': loadContentOutputLib(mocks, projectConfig),
