        './common/tokenUsageComment.js': { postTokenUsageComments: function() {} },
        './config.js': { STATUSES: { IN_REVIEW: 'In Review' } },
        './configLoader.js': configLoaderMock,
        './common/trackers.js': loadTrackersWc(mocks)
    };
