        './configLoader.js': configLoaderMock,
        './common/trackers.js': loadTrackersWc(mocks)
    };
    return loadModule('js/writeContentOutput.js', makeRequire(modules), Object.assign({}, mocks || {}));
}

function makeParams(overrides) {
